//! The conservative box test as it was before flyingrobots/bunny#258, kept as the reference
//! oracle for the faster `TraceRay::box_entry` (the performance chapter's Fidelity Rule).
//!
//! `slab`, `reciprocal`, `scaled`, `map2` and `pair` are copied verbatim from
//! `crates/bunny-query/src/trace.rs` at that revision. `box_entry` is the old method body,
//! with the ray's origin, direction and reciprocals read through the public accessors
//! instead of the private fields, which held exactly those values. Do not edit this file to
//! follow the library: it is the definition the library must keep matching.

use bunny_geom::FixedAabb3;
use bunny_linalg::FixedVec3;
use bunny_num::FixedQ32_32;
use bunny_query::TraceRay;

/// Reciprocals are `floor(2^63 / |d|)`.
const RECIPROCAL_BITS: u32 = 63;
/// `(n * reciprocal) >> 31` is `n * 2^32 / |d|`, a raw Q32.32 distance.
const RECIPROCAL_SHIFT: u32 = RECIPROCAL_BITS - FixedQ32_32::FRACTIONAL_BITS;

const fn raw3(v: FixedVec3) -> [i64; 3] {
    [v.x.raw(), v.y.raw(), v.z.raw()]
}

/// The old `TraceRay::box_entry`, bit for bit.
pub(crate) fn box_entry(
    ray: &TraceRay,
    aabb: &FixedAabb3,
    t_max: FixedQ32_32,
) -> Option<FixedQ32_32> {
    let (origin, direction) = (raw3(ray.origin()), raw3(ray.direction()));
    let reciprocals = direction.map(reciprocal);
    let limit = u64::try_from(t_max.raw()).ok()?;
    let lines = map2(origin, direction, pair);
    let bounds = map2(raw3(aabb.min), raw3(aabb.max), pair);
    let [x, y, z] = map2(map2(lines, reciprocals, pair), bounds, slab);
    let (x, y, z) = (x?, y?, z?);
    let enter = x.0.max(y.0).max(z.0);
    let exit = x.1.min(y.1).min(z.1);
    if enter > exit || enter > limit {
        return None;
    }
    i64::try_from(enter).ok().map(FixedQ32_32::from_raw)
}

/// Applies `f` to matching components of two triples.
#[inline]
fn map2<A, B, C>(lhs: [A; 3], rhs: [B; 3], f: impl Fn(A, B) -> C) -> [C; 3] {
    let ([a0, a1, a2], [b0, b1, b2]) = (lhs, rhs);
    [f(a0, b0), f(a1, b1), f(a2, b2)]
}

const fn pair<A, B>(lhs: A, rhs: B) -> (A, B) {
    (lhs, rhs)
}

/// Bounds `(lower, upper)` on the distances at which a ray is inside one axis slab, from the
/// ray's `(origin, direction)` on that axis, its reciprocal and the slab's `(min, max)`.
#[inline]
fn slab(
    ((origin, direction), reciprocal): ((i64, i64), u64),
    bounds: (i64, i64),
) -> Option<(u64, u64)> {
    let origin = i128::from(origin);
    let (min, max) = (i128::from(bounds.0), i128::from(bounds.1));
    if direction == 0 {
        return (min <= origin && origin <= max).then_some((0, u64::MAX));
    }
    let (near, far) =
        if direction > 0 { (min - origin, max - origin) } else { (origin - max, origin - min) };
    // A negative far plane is behind the origin. Both differences fit `u64`.
    let far = u64::try_from(far).ok()?;
    let near = u64::try_from(near).unwrap_or(0);
    Some((scaled(near, reciprocal), scaled(far, reciprocal + 1).saturating_add(1)))
}

/// `floor(2^63 / |d|)`, or zero for a zero component.
const fn reciprocal(direction: i64) -> u64 {
    match direction.unsigned_abs() {
        0 => 0,
        magnitude => (1_u64 << RECIPROCAL_BITS) / magnitude,
    }
}

/// `floor(value * reciprocal / 2^31)`, saturating.
#[inline]
fn scaled(value: u64, reciprocal: u64) -> u64 {
    let product = u128::from(value) * u128::from(reciprocal);
    u64::try_from(product >> RECIPROCAL_SHIFT).unwrap_or(u64::MAX)
}
